# liszt icon map - the curated source of truth for src/icons_tab.h.
# Regenerate the header with: sh scripts/gen-icons-tab.sh
#
# Line format (whitespace-separated, '#' comments):
#   n NAME  U+XXXX   exact filename (regular files), case-sensitive
#   d NAME  U+XXXX   exact directory name, case-sensitive
#   x .EXT  U+XXXX   suffix, matched case-insensitively (stored folded)
#   t LL    U+XXXX   filetype default, LS_COLORS label (fi di ln or ...)
#
# Seeded 2026-07-19 from eza 0.23's icon mapping (the factual
# key-to-Nerd-Font-codepoint associations; our own curation and
# format). Curation decisions: no open/closed folder distinction
# (liszt never reads directories to pick a glyph); unknown files with
# and without extensions both fall to fi (eza splits these); no ex=
# default (keeps the statless plan); pi/so/bd/cd default to fi until
# curated. Glyphs must be single codepoints in ASCII/PUA/SPUA ranges;
# the generator enforces the invariants.

t fi U+F15B
t di U+E5FF
t ln U+F481
t or U+F127

